 add('FIELD','Field dimensions','Source PDF geometry; not field measured','Verify finished walls, squareness, floor level, window trim/sill and service locations; return marked plan','Installer / cabinet maker','hold');
 add('SHOP','Shop drawings','Frameless full-overlay proposal','Submit signed plans, elevations, sections, construction, fronts, fillers, fixings, toe kicks and installation sequence','Cabinet maker','hold');
 add('HARDWARE','Hardware and machining','Runner/hinge families proposed; final SKUs pending','Confirm drawer load, length, clearances, drawer-box formulas, hinge count, cup/plate boring and pull model','Cabinet maker','hold');
 add('APPLIANCES','Appliance package','Wolf 36 proposed; refrigerator, dishwasher and hood TBD','Attach current installation sheets; confirm range adjustment, refrigerator clear opening/ventilation and all service/door envelopes','Owner / appliance supplier','hold');
 if(k.rangeModel==='wolf36'&&Math.abs(l.top-36.5)>.0625)add('HEIGHT','Range / counter height',fixed(l.top)+' in counter; 36.5 in modeled Wolf cooktop','Coordinate range adjustment and counter assembly. Test Match Wolf height; do not assume leveling range','Installer / fabricator','conflict');
 const left=l.range?.run==='south'?(l.range.x-D.west)*12-l.range.width/2-k.counterDepth:null,right=l.range?.run==='south'&&l.fridge?.run==='south'?(l.fridge.x-l.fridge.width/24-l.range.x-l.range.width/24)*12:null;
 if((left!==null&&left<12)||(right!==null&&right<15))add('LANDING','Cooking landing space',fixed(left)+' in before west counter return; '+(right===null?'TBD':fixed(right))+' in toward fridge','Review range/fridge wall. NKBA planning guidance calls for 12 in on one side and 15 in on the other; not a code certification','Designer / owner','conflict');
 if(right!==null&&right<27)add('SHARED','Shared range / fridge landing',fixed(right)+' in between appliances','Review shared landing use. Consider relocating refrigerator or revising the corner; compare against NKBA combined landing guidance','Designer / owner');
 add('SINK','Sink and faucet templates',s.sinkWidth+' × '+s.sinkDepth+' in illustrative opening; '+s.faucetHoles+' faucet/deck holes','Select sink and faucet; obtain certified DXF, minimum base size, reveal, corner radii, support, hole locations and window swing clearance','Owner / fabricator','hold');
 add('SUPPORT','Island and appliance-span support',k.seatingOverhang+' in seating overhang; '+fixed(k.islandWidth-k.seatingOverhang-k.baseDepth-2.25)+' in void behind bases','Fabricator and maker to design concealed steel/blocking, anchorage and dishwasher-span support for selected stone. No generic bracket spacing is specified','Fabricator / cabinet maker','hold');
 add('SLAB','Slab, seams and template',s.material+'; '+s.slabMm+' mm; '+s.product,'Approve actual slab/lot, usable size, vein direction, seam drawing, transport/access and field template. Area totals are not slab order quantities','Owner / fabricator','hold');
 add('SPLASH','Backsplash and hood interface',s.backsplash+' / '+s.splashMaterial+'; hood underside '+s.hoodBottom+' in AFF','Verify substrate/adhesive, heat compatibility behind Wolf, outlets, returns, finished thickness and sealant joints','Fabricator / installer','hold');
 add('FINISH','Finish sample and grain',m.finish+'; '+m.finishNote,'Approve physical finish sample and full front/grain sequence; approve sheen and edge banding','Owner / cabinet maker');
 if(st.buildUp<-.001)add('BUILDUP','Stone exceeds assembly thickness',fixed(st.buildUp)+' in available build-up','Increase countertop assembly thickness or select thinner slab','Designer','conflict');
