 if(l.fridge&&m.fridgeClearHeight>=l.fridge.h*12)add('BRIDGE','No room for refrigerator bridge',m.fridgeClearHeight+' in clear height','Lower clear opening or raise cabinet top within room constraints','Designer','conflict');
